// Generated by tools/prepare_web.py. Each release has an isolated complete cache.
const VERSION = __VERSION__;
const FILES = __FILES__;
const PREFIX = 'lume-offline-' + new URL(self.registration.scope).pathname + '-';
const CACHE = PREFIX + VERSION;
const urls = FILES.map(file => new URL(file, self.registration.scope).href);

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    try {
      for (let i = 0; i < urls.length; i++) {
        const response = await fetch(urls[i], {cache: 'reload'});
        if (!response.ok) throw new Error('Download failed: ' + urls[i]);
        await cache.put(urls[i], response);
        for (const client of await self.clients.matchAll({includeUncontrolled: true})) {
          client.postMessage({type: 'DOWNLOAD_PROGRESS', done: i + 1, total: urls.length});
        }
      }
      // Updates wait for all old game windows to close; never replace a running engine.
      if (!self.registration.active) await self.skipWaiting();
    } catch (error) {
      await caches.delete(CACHE);
      throw error;
    }
  })());
});

self.addEventListener('activate', event => {
  // Activation happens only after tabs using the previous version have closed.
  event.waitUntil((async () => {
    for (const key of await caches.keys()) {
      if (key.startsWith(PREFIX) && key !== CACHE) await caches.delete(key);
    }
  })());
});

self.addEventListener('message', event => {
  if (event.data?.type === 'REPAIR_OFFLINE') {
    event.waitUntil((async () => {
      try {
        const cache = await caches.open(CACHE);
        for (let i = 0; i < urls.length; i++) {
          if (!await cache.match(urls[i])) {
            const response = await fetch(urls[i], {cache: 'reload'});
            if (!response.ok) throw new Error('Download failed');
            await cache.put(urls[i], response);
          }
          event.source?.postMessage({type: 'DOWNLOAD_PROGRESS', done: i + 1, total: urls.length});
        }
        event.ports[0]?.postMessage({ready: true});
      } catch { event.ports[0]?.postMessage({ready: false}); }
    })());
    return;
  }
  if (event.data?.type !== 'CHECK_OFFLINE') return;
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    const results = await Promise.all(urls.map(url => cache.match(url)));
    event.ports[0]?.postMessage({ready: results.every(Boolean), version: VERSION});
  })());
});

self.addEventListener('fetch', event => {
  if (event.request.method !== 'GET') return;
  const url = new URL(event.request.url);
  if (!url.href.startsWith(self.registration.scope)) return;
  const key = event.request.mode === 'navigate'
    ? new URL('index.html', self.registration.scope).href
    : url.origin + url.pathname;
  if (!urls.includes(key)) return;
  event.respondWith((async () => {
    const cached = await (await caches.open(CACHE)).match(key);
    return cached || fetch(event.request);
  })());
});
